M.ById = {}
for _, skill in ipairs(M.Skills) do
    M.ById[skill.id] = skill
end

M.OuterSkills = {}
M.InnerSkills = {}
M.GeneralSkills = {}
for _, skill in ipairs(M.Skills) do
    if skill.kind == "外攻招式" then table.insert(M.OuterSkills, skill) end
    if skill.kind == "内攻招式" then table.insert(M.InnerSkills, skill) end
    if skill.kind == "通用精研" then table.insert(M.GeneralSkills, skill) end
end

return M
